		prec[cntIds][0] = mask, prec[cntIds][1] = left, prec[cntIds][2] = putk;
		cntIds++;
		return;
	}
	gen(iter + 1, mask, left, putk);
	if (iter < 12)
		gen(iter + 1, mask ^ (1 << iter), left, putk + 1);		
	else {
		if (iter - 12 < 4) {
			int addMask = (7 << (3 * (iter - 12))) ^ (7 << (3 * ((iter - 12 + 1) & 3)));
			if (!(addMask & mask))
				gen(iter + 1, mask ^ addMask, left ^ (1 << (iter - 12)) ^ (1 << ((iter - 12 + 1) & 3)), putk + 1);
		} else {
			if (iter - 16 < 4) {
				int addMask = (7 << (3 * (iter - 16)));
				if (!(addMask & mask))
					gen(iter + 1, mask ^ addMask, left ^ (1 << (iter - 16)), putk + 1);
			} else {
				int addMask = (1 << (3 * (iter - 20))) ^ (1 << ((3 * (iter - 20) - 1) & 3));
				if (!(addMask & mask))
					gen(iter + 1, mask ^ addMask, left, putk + 1);
			}
		}
	}
}

void countPrec() {
	cntIds = 0;
	gen(0, 0, 0, 0);
}

const int cnt0 = 8;
const int mask0[cnt0] = {1, 2, 4, 8, 3, 6, 12, 9};

int gen0(int iter, int taken, int left) {
	if (left > cnt0 - iter)
		return 0;
	if (iter == cnt0)
		return 1;
	int ans = gen0(iter + 1, taken, left);
	if (left && !(taken & mask0[iter]))
		add(ans, gen0(iter + 1, taken | mask0[iter], left - 1));
	return ans;
}

void countD(int n0, int k0) {
	countPrec();

	for (int k = 0; k <= k0; k++)
		for (int taken = 0; taken < (1 << 4); taken++)
			d[0][k][taken] = gen0(0, taken, k);

	for (int n = 1; n <= n0; n++) {
		for (int k = 0; k <= k0; k++) {
			for (int taken = 0; taken < (1 << 4); taken++) {
				int &cur = d[n][k][taken];
				cur = 0;
				if (!k) {
					cur = 1;
					continue;
				}
				int maskFail = 0;
				for (int i = 0; i < 4; i++) {
					if (!((taken >> i) & 1))
						continue;
					maskFail ^= (7 << (3 * i));
				}

				for (int maskId = 0; maskId < cntIds; maskId++) {
					int mask = prec[maskId][0], left = prec[maskId][1], putk = prec[maskId][2];
					if (mask & maskFail)
						continue;
					if (putk > k)
						continue;
					left |= taken;
					add(cur, d[n - 1][k - putk][left]);
				}
			}
		}
	}
}

bool solve() {
	int n, k;
	if (scanf("%d%d", &n, &k) < 1)
		return 0;

	countD(n, k);
	int res = d[n][k][0];
	for (int i = 1; i <= k; i++)
		res = mult(res, i);
	printf("%d\n", res);
	return 1;
}

